// WARNING: reset only a disposable demo database.
MATCH (n) DETACH DELETE n;

CREATE CONSTRAINT document_id IF NOT EXISTS
FOR (d:Document) REQUIRE d.documentId IS UNIQUE;
CREATE CONSTRAINT chunk_id IF NOT EXISTS
FOR (c:Chunk) REQUIRE c.chunkId IS UNIQUE;
CREATE CONSTRAINT entity_id IF NOT EXISTS
FOR (e:Entity) REQUIRE e.entityId IS UNIQUE;
CREATE CONSTRAINT fact_id IF NOT EXISTS
FOR (f:Fact) REQUIRE f.factId IS UNIQUE;

MATCH (n)
OPTIONAL MATCH (n)-[r]->(m)
RETURN n, r, m;

MATCH (n)
OPTIONAL MATCH (n)-[r]->(m)
RETURN n, r, m;

// Surface forms remain but the former identity and merge rationale are gone.
OPTIONAL MATCH (loser:Entity {entityId: 'DRUG-PARACETAMOL'})
OPTIONAL MATCH (oldFact:Fact {factId: 'DRUG-PARACETAMOL|TREATS|IND-FEVER'})
RETURN count(loser) AS recoverableEntityCount,
       count(oldFact) AS recoverableFactCount,
       'A reliable split requires external history or reconstruction' AS conclusion;

