MATCH p=(split:ResolutionDecision {decisionId: 'DEC-SPLIT-001'})-[:SUPERSEDES]->(merge:ResolutionDecision)
RETURN p, split.status AS currentDecisionStatus,
       merge.status AS previousDecisionStatus;

